# محاكي مستقل يطبّق صيغ الاكسل حرفياً (مو من كود النظام) — للمقارنة
import math, json, random, sys

DEV={0:10000,1:10200,2:10400,3:10600,4:10800,5:11000,6:11200,7:11400,8:11600,9:11800,
10:12000,11:12200,12:12400,13:12600,14:12800,15:13000,16:13200,17:13400,18:13600,19:13800,
20:14000,21:17750,22:18000,23:18250,24:18500,25:18750,26:19000,27:19250,28:19500,29:19750,
30:20000,31:20250,32:20500,33:20750,34:21000,35:21250,36:21500,37:21750,38:22000,39:22250,
40:25000,41:26000,42:27000,43:28000,44:29000,45:30000,46:31000,47:32000,48:33000,49:34000,
50:35000,51:36000,52:37000,53:38000,54:39000,55:40000,56:41000,57:42000,58:43000,59:44000,
60:45000,61:46000,62:47000,63:48000,64:49000,65:50000,66:51000,67:52000,68:53000,69:54000,
70:55000,71:56000,72:57000,73:58000,74:59000,75:60000,76:61000,77:62000,78:63000,79:64000,80:65000}
CAB={1:1000,2:1000,3:1000,4:1000,5:800,6:800,7:800,8:800,9:800,10:800,
11:750,12:745,13:745,14:737,15:735,16:700,17:705,18:700,19:695,20:692,
21:690,22:690,23:690,24:690,25:690,26:690,27:690,28:690,29:690}

def F(h):  # وزن ارتفاع التركيب
    return 1 if h<=4 else {5:1.15,6:1.3,7:1.5,8:1.7}.get(h,2)
def O(h):  # وزن ارتفاع التسليك
    return 2 if h>=5 else 1
def Lval(m):  # L = سعر المتر × الأمتار
    if m<=0: return 0
    return (710 if m>=30 else CAB[m])*m

def calc(rows, e58):
    """rows: كل صف يمثّل جهاز واحد بالاكسل"""
    key=min(max(e58,0),80)
    Gsum=0.0; Psum=0.0; Rsum=0.0; Scount=0; Ecount=0
    for r in rows:
        C=r['install']; E=1 if C>0 else 0
        Ecount+=E
        G = C*F(r['h'])*E if not r['wiring'] else 0
        Gsum+=G
        if r['wiring']:
            K = DEV[key]*E - G
            M = O(r['wh'])*r['N']*Lval(r['m'])
            Psum += max(M,K)
        if r.get('prog',0)>0:
            Rsum+=r['prog']; Scount+=1
    G58=Gsum+Psum
    if 1<=Ecount<=4:   G59=max(G58,Ecount*14000)
    elif 5<=Ecount<=8: G59=max(G58,Ecount*12500)
    elif 9<=Ecount<=16:G59=max(G58,Ecount*11500)
    elif Ecount>=17:   G59=max(G58,Ecount*10000)
    else:              G59=G58
    R59={0:Rsum,1:max(Rsum,13500),2:max(Rsum,24500),3:max(Rsum,32500)}.get(Scount,max(Rsum,35000))
    return math.ceil((G59+R59)/1000)*1000

if __name__=='__main__':
    print(json.dumps(calc(*json.loads(sys.argv[1]))))
